CREATE OR REPLACE VIEW AVOIRFC_VIDE AS
select av."ID",av."DESIGNATION",av."IDMAGASIN",av."DATY",av."REMARQUE",av."ETAT",av."IDORIGINE",av."IDCLIENT",av."IDVENTE",av."IDMOTIF",av."IDCATEGORIE",av."IDTYPEAVOIR",av."NUMAVOIR",av."IDRISTOURNE",av."IDREPRESENTANT", CAST(' ' AS varchar(100)) AS iddevise from AVOIRFC av;
